namespace RonSijm.FluidHumidifier.Factories.MediaPackageV2;

public class ChannelFactory(string resourceName = null, Action<Humidifier.MediaPackageV2.Channel> factoryAction = null) : ResourceFactory<Humidifier.MediaPackageV2.Channel>(resourceName)
{

    internal InnerChannelInputSwitchConfigurationFactory InputSwitchConfigurationFactory { get; set; }

    internal InnerChannelMultiviewConfigurationFactory MultiviewConfigurationFactory { get; set; }

    internal InnerChannelOutputHeaderConfigurationFactory OutputHeaderConfigurationFactory { get; set; }

    protected override Humidifier.MediaPackageV2.Channel Create()
    {
        var channelResult = CreateChannel();
        factoryAction?.Invoke(channelResult);

        return channelResult;
    }

    private Humidifier.MediaPackageV2.Channel CreateChannel()
    {
        var channelResult = new Humidifier.MediaPackageV2.Channel
        {
            GivenName = InputResourceName,
        };

        return channelResult;
    }
    public override void CreateChildren(Humidifier.MediaPackageV2.Channel result)
    {
        base.CreateChildren(result);

        result.InputSwitchConfiguration ??= InputSwitchConfigurationFactory?.Build();
        result.MultiviewConfiguration ??= MultiviewConfigurationFactory?.Build();
        result.OutputHeaderConfiguration ??= OutputHeaderConfigurationFactory?.Build();
    }

} // End Of Class

